def count_divisors(n):
    """Calculates the number of positive divisors of n."""
    if n == 1:
        return 1

    count = 1
    d = 2
    temp_n = n

    while d * d <= temp_n:
        exponent = 0
        while temp_n % d == 0:
            exponent += 1
            temp_n //= d
        if exponent > 0:
            count *= (exponent + 1)
        d += 1

    if temp_n > 1:
        count *= 2

    return count

def solve_problem(k):
    if k <= 0:
        return None

    n = 2 * (k**3)
    d_n = count_divisors(n)
    required = 2 * k

    return d_n == required

# Test k from 1 to 20
results = {}
for k in range(1, 21):
    holds = solve_problem(k)
    results[k] = holds

print("k | D(2k^3) = 2k")
